export const getDeleteUserCallbackUrl = (params?: DeleteUserCallbackParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/auth/delete-user/callback?${stringifiedParams}` : `/v1/auth/delete-user/callback`
}

