export const getExpoAuthorizationProxyUrl = (params?: ExpoAuthorizationProxyParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/auth/expo-authorization-proxy?${stringifiedParams}` : `/v1/auth/expo-authorization-proxy`
}

export const expoAuthorizationProxy = async (params?: ExpoAuthorizationProxyParams, options?: Parameters<typeof customFetch>[1]): Promise<unknown> => {

  return customFetch<unknown>(getExpoAuthorizationProxyUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





